using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Rendering;using Newtonsoft.Json;
public static class LabDoorApply{
 static string A="Assets/Afrer_Seconds/05.Model/";static string E=>A+"Environment/B5/";static string P=>A+"Props/B5/Materials/";
 static GameObject Child(string name,Transform parent){var g=new GameObject(name);g.transform.SetParent(parent,false);return g;}
 static Material Load(string n)=>AssetDatabase.LoadAssetAtPath<Material>(P+n+".mat");
 static Material Dedicated(string n,Material template,Color color){var p=E+"Materials/"+n+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(p);if(!m){m=new Material(template);m.name=n;AssetDatabase.CreateAsset(m,p);}m.SetColor("_BaseColor",color);return m;}
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_B5_Circular.unity"))throw new Exception("Saved B5 edit scene required");var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;var room=root.Find("C01_Experiment_Art");var doors=root.Find("Pocket_Doors_Open").Cast<Transform>().Where(d=>Vector3.Distance(d.position,room.position)<12).ToArray();if(doors.Length!=3)throw new Exception("Expected 3 C01 doors");var logs=new List<string>();Application.LogCallback cb=(m,st,t)=>{if(t==LogType.Warning||t==LogType.Error||t==LogType.Exception)logs.Add(m);};Application.logMessageReceived+=cb;
 try{string path=E+"CDR_ClinicalPortal.fbx";AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport|ImportAssetOptions.ForceUpdate);var imp=(ModelImporter)AssetImporter.GetAtPath(path);imp.isReadable=true;imp.importAnimation=false;imp.importLights=false;imp.importCameras=false;imp.materialImportMode=ModelImporterMaterialImportMode.ImportStandard;imp.SaveAndReimport();
 var accent=Dedicated("CDR_Accent",Load("CP_Blue"),new Color(.045f,.22f,.23f,1));var glass=Dedicated("CDR_Glass",Load("CP_Glass"),new Color(.23f,.44f,.47f,.21f));var status=Dedicated("CDR_Status",Load("CP_Dark"),new Color(.08f,.38f,.32f,1));status.EnableKeyword("_EMISSION");status.SetColor("_EmissionColor",new Color(.04f,.36f,.28f)*1.4f);
 var mats=new Dictionary<string,Material>{{"S1_Coat",Load("CP_Coat")},{"S1_Steel",Load("CP_Steel")},{"S1_Dark",Load("CP_Rubber")},{"CDR_Accent",accent},{"CDR_Glass",glass},{"CDR_Status",status}};
 foreach(var d in doors){var existing=d.Find("Clinical_Portal");if(existing)UnityEngine.Object.DestroyImmediate(existing.gameObject);var archived=d.Find("Previous_Rectangular_Door_Inactive");if(!archived){archived=Child("Previous_Rectangular_Door_Inactive",d).transform;foreach(var t in d.Cast<Transform>().Where(t=>t!=archived).ToArray())t.SetParent(archived,true);archived.gameObject.SetActive(false);}
 var portal=Child("Clinical_Portal",d).transform;portal.rotation=Quaternion.LookRotation((d.position-room.position).normalized);var visual=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(path),portal);PrefabUtility.UnpackPrefabInstance(visual,PrefabUnpackMode.Completely,InteractionMode.AutomatedAction);visual.name="Portal_Frame";
 foreach(var mf in visual.GetComponentsInChildren<MeshFilter>().ToArray()){var rend=mf.GetComponent<Renderer>();rend.sharedMaterials=rend.sharedMaterials.Select(m=>mats[m.name]).ToArray();if(mf.name=="CDR_Frame"){var c=mf.gameObject.AddComponent<MeshCollider>();c.sharedMesh=mf.sharedMesh;}else{string side=mf.name.Contains("Left")?"Left":"Right";float sign=side=="Left"?-1:1;var leaf=Child("Leaf_"+side,portal).transform;mf.transform.SetParent(leaf,true);var c=leaf.gameObject.AddComponent<BoxCollider>();c.center=new Vector3(sign*.605f,1.4065f,0);c.size=new Vector3(1.21f,2.767f,.112f);Child(side+"_Closed",portal).transform.localPosition=Vector3.zero;Child(side+"_Open",portal).transform.localPosition=new Vector3(sign*1.235f,0,0);leaf.localPosition=new Vector3(sign*1.235f,0,0);}}
 var kp=AssetDatabase.LoadAssetAtPath<GameObject>(A+"Props/Common/LP_Keypad.prefab");foreach(float face in new[]{-1f,1f}){var k=(GameObject)PrefabUtility.InstantiatePrefab(kp,portal);k.name="Keypad_"+(face<0?"Room":"Tunnel");k.transform.localPosition=new Vector3(1.48f,1.35f,face*.31f);k.transform.localRotation=Quaternion.Euler(0,face<0?180:0,0);}
 }
 Physics.SyncTransforms();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);foreach(var m in new[]{accent,glass,status}){EditorUtility.SetDirty(m);AssetDatabase.SaveAssetIfDirty(m);}
 }finally{Application.logMessageReceived-=cb;}
 var result=new{scene=s.path,doors=doors.Select(d=>d.name).ToArray(),logs,oldDoors="inactive child preserved",runtimeCodeAdded=false};var o=Path.GetFullPath(Path.Combine(Application.dataPath,"../../../Docs/검수/2026-11-07_C01_Doors/apply.json"));File.WriteAllText(o,JsonConvert.SerializeObject(result,Formatting.Indented));return result;}
}
